103	diff --git a/build_tenants/abiogenesis/typescript/code/src/validator/qualification_resources.ts b/build_tenants/abiogenesis/typescript/code/src/validator/qualification_resources.ts
104	index 1d8e690b3..3a443e8f6 100644
105	--- a/build_tenants/abiogenesis/typescript/code/src/validator/qualification_resources.ts
106	+++ b/build_tenants/abiogenesis/typescript/code/src/validator/qualification_resources.ts
107	@@ -18,6 +18,24 @@ import { SELF_CONFORMANCE_REFERENCE_INPUT_SCHEMA, type SelfConformanceInput, typ
108	 import { canonicalEquals } from "../shared/value/index.js";
109	 const coord = (ref: string, digest: string): QualificationCoordinate => ({ ref, digest });
110	 const unique = (xs: readonly unknown[]) => new Set(xs).size === xs.length;
111	+// A disposable cache of a derived hash, never a resource/view or admission.
112	+// Every acquisition first authenticates each strict material's canonical base64
113	+// bytes against its digest and length. Only then do these four fields identify
114	+// the complete material value, including its bytes. Preserve record order.
115	+// This avoids serializing the same large record bodies for every provenance
116	+// view; cold acquisition, changed bytes and all other admission checks remain.
117	+const verifiedRecordSetDigests = new Map<string, string>();
118	+const RECORD_SET_MEMO_LIMIT = 256;
119	+function verifiedRecordSetDigest(records: readonly QualificationMaterial[]): string {
120	+  const key = hash(records.map(({ ref, path, digest, byteCount }) => ({ ref, path, digest, byteCount })));
121	+  const known = verifiedRecordSetDigests.get(key);
122	+  if (known !== undefined) return known;
123	+  const digest = hash(records);
124	+  if (verifiedRecordSetDigests.size >= RECORD_SET_MEMO_LIMIT)
125	+    verifiedRecordSetDigests.delete(verifiedRecordSetDigests.keys().next().value!);
126	+  verifiedRecordSetDigests.set(key, digest);
127	+  return digest;
128	+}
129	 export function isQualificationReferenceForm(value: unknown): value is { representation: "resource_refs_v1" } {
130	   return value !== null && typeof value === "object" && "representation" in value && value.representation === "resource_refs_v1";
131	 }
132	@@ -182,7 +200,7 @@ export class QualificationResources {
133	     const key = selection.resource.ref + ":" + selection.entry.ref, prior = this.provenanceViews.get(key);
134	     if (prior !== undefined) return prior;
135	     const m = this.manifest(selection.resource), records = p.records.map(s => this.value<QualificationMaterial>(this.selection(m, s.entryKind, s.entry), "material"));
136	-    if (!unique(records.map(x => x.ref)) || hash(records) !== p.recordSet.digest) throw new TypeError("qualification_provenance_record_set");
137	+    if (!unique(records.map(x => x.ref)) || verifiedRecordSetDigest(records) !== p.recordSet.digest) throw new TypeError("qualification_provenance_record_set");
138	     const view = deepFreeze({ ...p, records }); this.provenanceViews.set(key, view); return view;
139	   }
140	 }

