39	export function isQualificationReferenceForm(value: unknown): value is { representation: "resource_refs_v1" } {
40	  return value !== null && typeof value === "object" && "representation" in value && value.representation === "resource_refs_v1";
41	}
42	function material(value: unknown): QualificationMaterial {
43	  if (!v.is(QUALIFICATION_MATERIAL_SCHEMA, value)) throw new TypeError("qualification_resource_material_shape");
44	  const bytes = Buffer.from(value.contentBase64, "base64");
45	  if (bytes.toString("base64") !== value.contentBase64 || bytes.length !== value.byteCount || sha256Bytes(bytes) !== value.digest)
