48	}
49	/** Immutable operation dependency, acquired once at raw/cold ingress. Its maps
50	 * are private; neither this object nor a selected body supplies ABG authority. */
51	export class QualificationResources {
52	  readonly assertion: QualificationResourceAssertion;
53	  private readonly manifests = new Map<string, QualificationResourceManifest>();
54	  private readonly tables = new Map<string, Map<string, JsonValue>>();
55	  private readonly scopeViews = new Map<string, { scope: QualificationScope; normalized: QualificationInternedScope }>();
56	  private readonly assessmentViews = new Map<string, ResolvedQualificationAssessment>();
57	  private readonly provenanceViews = new Map<string, QualificationConstructionProvenance>();
58	  private readonly proofs: readonly AbgHistoricalDeclarationProof[];
59	  private readonly proofDigests = new Map<AbgHistoricalDeclarationProof, string>();
60	  constructor(assertion: unknown, additionalProofs: readonly AbgHistoricalDeclarationProof[] = []) {
61	    if (!v.is(QUALIFICATION_RESOURCE_ASSERTION_SCHEMA, assertion)) throw new TypeError("qualification_resource_assertion_shape");
