63	    this.assertion = deepFreeze(JSON.parse(JSON.stringify(assertion))) as QualificationResourceAssertion;
64	    this.proofs = Object.freeze([...this.assertion.declarationProofs, ...additionalProofs]);
65	    const proofKeys = this.proofs.map(p => [p.catalog.basisDigest, p.catalog.readinessBasisDigest, p.catalogView.viewDigest].join(":"));
66	    if (!unique(proofKeys)) throw new TypeError("qualification_declaration_ambiguous");
67	    for (const proof of this.proofs) this.proofDigests.set(proof, hash(proof));
68	    for (const m of this.assertion.manifests) {
69	      if (!identity(m, "resourceRef", "resourceDigest", "qualification-resource://abiogenesis/") || this.manifests.has(m.resourceRef))
