92	        if (kind === "verification_recipe") v.parse(QUALIFICATION_VERIFICATION_RECIPE_SCHEMA, JSON.parse(Buffer.from(m.contentBase64, "base64").toString("utf8")));
93	        break;
94	      }
95	      case "inventory": {
96	        const i = v.parse(QUALIFICATION_INVENTORY_SCHEMA, value);
97	        if (!identity(i, "inventoryRef", "inventoryDigest", "qualification-inventory://abiogenesis/") || !unique(i.members.map(x => x.ref)) || !unique(i.members.map(x => x.path)) || !unique(i.selectedRoots) || i.selectedRoots.length === 0)
