105	      }
106	      case "law": {
107	        const law = v.parse(QUALIFICATION_LAW_BASIS_SCHEMA, value);
108	        if (!identity(law, "lawBasisRef", "lawBasisDigest", "qualification-law://abiogenesis/")) throw new TypeError("qualification_law_identity");
109	        id = coord(law.lawBasisRef, law.lawBasisDigest); break;
110	      }
111	      case "tenant_manifest": {
112	        const t = v.parse(TENANT_CONFORMANCE_MANIFEST_SCHEMA, value);
113	        if (qualificationIdentityDigest(t, "manifestRef", "manifestDigest") !== t.manifestDigest) throw new TypeError("qualification_tenant_identity");
114	        id = coord(t.manifestRef, t.manifestDigest); break;
115	      }
116	      case "coverage_catalog": {
117	        const c = v.parse(QUALIFICATION_COVERAGE_CATALOG_SCHEMA, value);
118	        if (!identity(c, "catalogRef", "catalogDigest", "qualification-coverage://abiogenesis/")) throw new TypeError("qualification_coverage_identity");
