129	   * across preparation/completion, never inferred from another invocation. */
130	  assessment(input: QualificationAssessmentInput, validate: (view: ResolvedQualificationAssessment) => void): ResolvedQualificationAssessment {
131	    const key = hash(input), known = this.assessmentViews.get(key);
132	    if (known !== undefined) return { ...known, input };
133	    const view = resolveQualificationAssessment(input, this);
134	    validate(view); deepFreeze(view.task);
135	    this.assessmentViews.set(key, Object.freeze(view)); return view;
136	  }
137	  selection(m: QualificationResourceManifest, entryKind: QualificationResourceSelection["entryKind"], entry: QualificationCoordinate): QualificationResourceSelection {
