210	export function resolveQualificationProof(proof: QualificationProofResource, resources?: QualificationResources): QualificationEmbeddedProofResource {
211	  if (!isQualificationReferenceForm(proof)) return proof;
212	  if (resources === undefined) throw new TypeError("qualification_resource_dependency_missing");
