const spanBody={kind:'graph_function_application',relationKind:'re_enter',inputContractRef:contract('refresh-model'),outputContractRef:contract('request'),graphFunctionRef:ref('graph-function','root'),sourceProgramLocusRef:ref('locus','refreshModel'),targetProgramLocusRef:ref('locus','model'),maxApplications:1};
export const spanApplication={...spanBody,applicationRef:`graph-function-application://abiogenesis/${hash(spanBody).slice(7)}`};
export function refreshModel(input) {
 const state=versioned('fixture_refreshed_model',{observationSnapshot:input.observationSnapshot,evaluation:input});
 if(input.observationSnapshot.phase===0){
  // The refreshed model retains the actual admitted action evaluation and current observation.
  // Its closed fixture policy requests the second declared task through ordinary graph-span reentry.
  const targetInput={...state.observationSnapshot,phase:1,task:{...state.observationSnapshot.task,payload:'selected second action'},priorRefreshedModel:state};
  const targetInputDigest=hash(targetInput);
  return realize('refreshModel',input,identified('graph_span_selection','graph-span-reentry-projection','projectionRef','projectionDigest',{disposition:'re_enter',applicationRef:spanApplication.applicationRef,graphFunctionRef:spanBody.graphFunctionRef,sourceProgramLocusRef:spanBody.sourceProgramLocusRef,targetProgramLocusRef:spanBody.targetProgramLocusRef,targetInputRef:`graph-span-input://product/${targetInputDigest.slice(7)}`,targetInputDigest,targetInput}));
 }
 return realize('refreshModel',input,versioned('graph_span_selection',{disposition:'continue',state}));

