42:/** Trailer identities (D5 disposition F-4): Opus 5.5 a Worker, Fable 5.1 the Executive, no trailer the owner;
52:  const trailers = [...message.matchAll(/^Co-Authored-By:\s*(.+?)\s*<[^>]*>\s*$/gimu)].map(m => m[1]);
53:  if (trailers.length > 1) throw new TypeError('more than one Co-Authored-By trailer');
54:  if (trailers.length === 0) return CONSTRUCTION_IDENTITIES.owner;
55:  const row = CONSTRUCTION_IDENTITIES[trailers[0]];
56:  if (row === undefined) throw new TypeError('unmapped Co-Authored-By trailer: ' + trailers[0]);

